import type { Metadata } from "next";

import { site } from "@/lib/site";

/**
 * The site's share image, generated by app/opengraph-image.tsx. Pages that
 * set `openGraph` lose the inherited file-based image, so they name it here.
 */
export const shareImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${site.name}: I build backend systems and AI-powered products.`,
};

/**
 * Metadata for one page. A page that sets `openGraph` or `twitter` replaces
 * the root layout's objects entirely (Next.js merges metadata shallowly), so
 * every page builds both in full here. The share image comes from
 * app/opengraph-image.tsx.
 */
export function pageMetadata({
  title,
  description,
  path,
  type = "website",
}: {
  /** Page title; the root layout's template appends the site name. */
  title: string;
  description: string;
  /** Path from the site root, used as the canonical URL. */
  path: string;
  type?: "website" | "article";
}): Metadata {
  const fullTitle = `${title} · ${site.name}`;
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type,
      locale: "en_IN",
      url: path,
      siteName: site.name,
      title: fullTitle,
      description,
      images: [shareImage],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [shareImage],
    },
  };
}
